// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title SerializationRegistry
 * @notice Manages serialization of structured data with role-based access
 * @dev Uses temporary storage slots for intermediate serialization state
 */
contract SerializationRegistry {

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN");
    bytes32 public constant SERIALIZER_ROLE = keccak256("SERIALIZER");

    mapping(bytes32 => mapping(address => bool)) private _roles;
    mapping(bytes32 => bytes) private _serializedData;
    mapping(address => uint256) private _nonces;

    // Temporary serialization buffer - uses predictable slot derivation
    mapping(bytes32 => bytes) private _tempBuffers;

    event DataSerialized(bytes32 indexed key, address indexed serializer);
    event RoleGranted(bytes32 indexed role, address indexed account);
    event TempBufferCreated(bytes32 indexed bufferId);

    modifier onlyRole(bytes32 role) {
        require(_roles[role][msg.sender], "AccessControl: unauthorized");
        _;
    }

    constructor() {
        _roles[ADMIN_ROLE][msg.sender] = true;
    }

    function grantRole(bytes32 role, address account) external onlyRole(ADMIN_ROLE) {
        _roles[role][account] = true;
        emit RoleGranted(role, account);
    }

    function hasRole(bytes32 role, address account) public view returns (bool) {
        return _roles[role][account];
    }

    /**
     * @notice Creates a temporary buffer for multi-step serialization
     * @dev Buffer ID is derived from sender and a sequential nonce
     * @return bufferId The identifier for the temporary buffer
     */
    function createTempBuffer(bytes calldata initialData) 
        external 
        onlyRole(SERIALIZER_ROLE) 
        returns (bytes32 bufferId) 
    {
        // Derive buffer ID from block.timestamp and sender for uniqueness
        bufferId = keccak256(abi.encodePacked(
            block.timestamp,
            msg.sender
        ));

        _tempBuffers[bufferId] = initialData;
        emit TempBufferCreated(bufferId);
        return bufferId;
    }

    /**
     * @notice Appends data to an existing temporary buffer
     * @param bufferId The buffer to append to
     * @param data The data to append
     */
    function appendToBuffer(bytes32 bufferId, bytes calldata data) 
        external 
        onlyRole(SERIALIZER_ROLE) 
    {
        require(_tempBuffers[bufferId].length > 0, "Buffer does not exist");
        _tempBuffers[bufferId] = abi.encodePacked(_tempBuffers[bufferId], data);
    }

    /**
     * @notice Finalizes a temporary buffer into permanent serialized storage
     * @param bufferId The buffer to finalize
     * @param storageKey The permanent storage key
     */
    function finalizeBuffer(bytes32 bufferId, bytes32 storageKey) 
        external 
        onlyRole(SERIALIZER_ROLE) 
    {
        require(_tempBuffers[bufferId].length > 0, "Buffer does not exist");

        // Serialize with version prefix and length encoding
        bytes memory serialized = abi.encodePacked(
            uint8(1), // version
            uint32(_tempBuffers[bufferId].length),
            _tempBuffers[bufferId]
        );

        _serializedData[storageKey] = serialized;

        // Clear temp buffer
        delete _tempBuffers[bufferId];

        emit DataSerialized(storageKey, msg.sender);
    }

    /**
     * @notice Reads serialized data
     * @param storageKey The key to read
     * @return The serialized bytes
     */
    function readSerialized(bytes32 storageKey) external view returns (bytes memory) {
        return _serializedData[storageKey];
    }

    /**
     * @notice Computes what a buffer ID would be for given parameters
     * @dev Useful for off-chain coordination
     */
    function computeBufferId(uint256 timestamp, address sender) 
        external 
        pure 
        returns (bytes32) 
    {
        return keccak256(abi.encodePacked(timestamp, sender));
    }

    /**
     * @notice Batch serialize multiple entries atomically
     * @param keys Array of storage keys
     * @param values Array of data values
     */
    function batchSerialize(bytes32[] calldata keys, bytes[] calldata values) 
        external 
        onlyRole(SERIALIZER_ROLE) 
    {
        require(keys.length == values.length, "Length mismatch");
        require(keys.length <= 50, "Batch too large");

        for (uint256 i = 0; i < keys.length; i++) {
            bytes memory serialized = abi.encodePacked(
                uint8(1),
                uint32(values[i].length),
                values[i]
            );
            _serializedData[keys[i]] = serialized;
            emit DataSerialized(keys[i], msg.sender);
        }
    }

    /**
     * @notice Emergency cleanup of orphaned temp buffers
     * @param bufferIds Array of buffer IDs to clean
     */
    function cleanupBuffers(bytes32[] calldata bufferIds) 
        external 
        onlyRole(ADMIN_ROLE) 
    {
        for (uint256 i = 0; i < bufferIds.length; i++) {
            delete _tempBuffers[bufferIds[i]];
        }
    }

    /**
     * @notice Get the current temp buffer contents (for verification)
     */
    function getTempBuffer(bytes32 bufferId) external view returns (bytes memory) {
        return _tempBuffers[bufferId];
    }
}
